//! Read-only OFX facade readiness planner for the future AEX bridge.
//!
//! This example consumes local JSON contracts generated by the AEX readiness
//! flow. It does not import an OFX SDK, start an OFX host, open `.aex` files,
//! or issue worker render/describe requests.

use serde::{Deserialize, Serialize};
use std::collections::BTreeSet;
use std::error::Error;
use std::fs::OpenOptions;
use std::io::{ErrorKind, Write};
use std::path::{Path, PathBuf};

