fn parse_aex_metadata_gate_report(text: &str) -> Result<AexMetadataGateSummary, serde_json::Error> {
    let input_contains_forbidden_tokens = aex_metadata_gate_contains_forbidden_tokens(text);
    let input = serde_json::from_str::<AexMetadataGateInput>(text)?;
    let status = sanitized_non_empty_string(input.status.clone(), input_contains_forbidden_tokens);
    let report_kind =
        sanitized_non_empty_string(input.report_kind.clone(), input_contains_forbidden_tokens);
    let publication_status = sanitized_non_empty_string(
        input.publication_status.clone(),
        input_contains_forbidden_tokens,
    );
    let fixture_gate_status = sanitized_non_empty_string(
        input.fixture_gate_summary.status.clone(),
        input_contains_forbidden_tokens,
    );
    let loader_gate_status = sanitized_non_empty_string(
        input.loader_gate_summary.status.clone(),
        input_contains_forbidden_tokens,
    );
    let identity_smoke_status = sanitized_non_empty_string(
        input.identity_smoke_summary.status.clone(),
        input_contains_forbidden_tokens,
    );
    let ofx_contract_status = sanitized_non_empty_string(
        input.ofx_contract_summary.status.clone(),
        input_contains_forbidden_tokens,
    );
    let fixture_gate_closed = input.fixture_gate_summary.status == "review_queue_not_approved"
        && !input.fixture_gate_summary.selected_fixture_present
        && !input.fixture_gate_summary.approval_approved
        && !input.fixture_gate_summary.approval_loader_enabled
        && !input.fixture_gate_summary.approval_real_aex_load_enabled
        && !input.fixture_gate_summary.approval_render_png_enabled;
    let loader_gate_closed = input.loader_gate_summary.status == "loader_gate_not_opened"
        && !input.loader_gate_summary.approved
        && !input.loader_gate_summary.loader_enabled
        && !input.loader_gate_summary.real_aex_load_enabled
        && input.loader_gate_summary.open_candidate_count == 0;
    let identity_smoke_no_load = input.identity_smoke_summary.status
        == "fixture_identity_smoke_ready_no_load"
        && !input.identity_smoke_summary.native_load_performed
        && !input.identity_smoke_summary.render_performed
        && !input.identity_smoke_summary.aex_loaded
        && !input.identity_smoke_summary.worker_started
        && !input.identity_smoke_summary.ofx_route_invoked
        && !input.identity_smoke_summary.ae_invoked
        && !input.identity_smoke_summary.private_payload_copied
        && !input.identity_smoke_summary.aex_render_correctness_evidence;
    let ofx_contract_deferred = input.ofx_contract_summary.status == "deferred-contract-only"
        && !input.ofx_contract_summary.ofx_host_may_load_aex
        && !input.ofx_contract_summary.ofx_adapter_may_load_aex
        && !input.ofx_contract_summary.broker_may_load_aex
        && !input.ofx_contract_summary.review_approved
        && !input.ofx_contract_summary.may_point_to_broker
        && !input.ofx_contract_summary.may_issue_describe
        && !input.ofx_contract_summary.may_issue_render_png;
    let top_level_no_load = !input.native_load_performed
        && !input.render_performed
        && !input.aex_loaded
        && !input.worker_started
        && !input.broker_load_or_render_allowed
        && !input.ofx_route_allowed
        && !input.ae_invoked
        && !input.private_payload_copied;
    let ready_for_ofx_review_no_load = !input_contains_forbidden_tokens
        && input.schema_version == 1
        && input.report_kind == "aex_metadata_gate_integration"
        && input.publication_status == "local-only"
        && input.status == "aex_metadata_gate_ready_no_load"
        && top_level_no_load
        && fixture_gate_closed
        && loader_gate_closed
        && identity_smoke_no_load
        && ofx_contract_deferred
        && input.blocked_reasons.is_empty();

    Ok(AexMetadataGateSummary {
        provided: true,
        status,
        report_kind,
        publication_status,
        ready_for_ofx_review_no_load,
        native_load_performed: input.native_load_performed,
        render_performed: input.render_performed,
        aex_loaded: input.aex_loaded,
        worker_started: input.worker_started,
        broker_load_or_render_allowed: input.broker_load_or_render_allowed,
        ofx_route_allowed: input.ofx_route_allowed,
        ae_invoked: input.ae_invoked,
        private_payload_copied: input.private_payload_copied,
        fixture_gate_status,
        fixture_selected: input.fixture_gate_summary.selected_fixture_present,
        fixture_approval_approved: input.fixture_gate_summary.approval_approved,
        fixture_loader_enabled: input.fixture_gate_summary.approval_loader_enabled,
        fixture_real_aex_load_enabled: input.fixture_gate_summary.approval_real_aex_load_enabled,
        fixture_render_png_enabled: input.fixture_gate_summary.approval_render_png_enabled,
        loader_gate_status,
        loader_gate_approved: input.loader_gate_summary.approved,
        loader_gate_loader_enabled: input.loader_gate_summary.loader_enabled,
        loader_gate_real_aex_load_enabled: input.loader_gate_summary.real_aex_load_enabled,
        loader_gate_open_candidate_count: input.loader_gate_summary.open_candidate_count,
        identity_smoke_status,
        identity_smoke_aex_loaded: input.identity_smoke_summary.aex_loaded,
        identity_smoke_ofx_route_invoked: input.identity_smoke_summary.ofx_route_invoked,
        identity_smoke_aex_render_correctness_evidence: input
            .identity_smoke_summary
            .aex_render_correctness_evidence,
        ofx_contract_status,
        ofx_contract_review_approved: input.ofx_contract_summary.review_approved,
        ofx_contract_ofx_host_may_load_aex: input.ofx_contract_summary.ofx_host_may_load_aex,
        ofx_contract_ofx_adapter_may_load_aex: input.ofx_contract_summary.ofx_adapter_may_load_aex,
        ofx_contract_broker_may_load_aex: input.ofx_contract_summary.broker_may_load_aex,
        blocked_reason_count: input.blocked_reasons.len(),
        input_contains_forbidden_tokens,
    })
}

