fn native_stage_plan_ready_for_ofx_review(summary: &NativeStagePlanSummary) -> bool {
    summary.provided
        && summary.no_load_stage_plan_ready
        && summary.worker_runtime_evidence_ready
        && (!summary.cleanroom_boundary_provided || summary.cleanroom_boundary_no_loader_or_sdk)
        && summary.selector_execution_blocked
        && summary.render_blocked
        && summary.ofx_route_blocked
        && !summary.input_contains_forbidden_tokens
}

fn loader_slice_review_ready_for_ofx_review(summary: &LoaderSliceReviewSummary) -> bool {
    summary.provided
        && summary.ready_for_manual_loader_slice_review_no_load
        && !summary.loader_slice_approved
        && !summary.loader_enabled
        && !summary.real_aex_load_enabled
        && !summary.native_loader_calls_allowed
        && !summary.broker_may_load_aex
        && !summary.worker_may_load_plugin
        && !summary.render_performed
        && !summary.ofx_route_allowed
        && !summary.input_contains_forbidden_tokens
}

fn loader_approval_ready_for_ofx_review(summary: &LoaderApprovalSummary) -> bool {
    summary.provided
        && summary.validation_status.as_deref()
            == Some("approved_for_loader_implementation_review_no_load")
        && summary.approval_accepted
        && summary.loader_review_approved
        && summary.loader_slice_review_packet_checked
        && summary.loader_slice_review_packet_status.as_deref()
            == Some("ready_for_manual_loader_slice_review_no_load")
        && summary
            .loader_slice_review_packet_checksum_algorithm
            .as_deref()
            == Some("fnv1a64-v1-noncryptographic")
        && !summary.native_load_performed
        && !summary.loader_enabled
        && !summary.real_aex_load_enabled
        && !summary.native_loader_calls_allowed
        && !summary.worker_may_load_plugin
        && !summary.broker_may_load_aex
        && !summary.render_performed
        && !summary.ofx_route_allowed
        && summary.receipt_allows_separate_loader_implementation_review
        && !summary.receipt_allows_native_aex_load
        && !summary.receipt_allows_worker_plugin_load
        && !summary.receipt_allows_render_png
        && !summary.receipt_allows_ofx_route
        && summary.blocked_reason_count == 0
        && !summary.input_contains_forbidden_tokens
}

fn aex_metadata_gate_ready_for_ofx_review(summary: &AexMetadataGateSummary) -> bool {
    summary.provided
        && summary.status.as_deref() == Some("aex_metadata_gate_ready_no_load")
        && summary.report_kind.as_deref() == Some("aex_metadata_gate_integration")
        && summary.publication_status.as_deref() == Some("local-only")
        && summary.ready_for_ofx_review_no_load
        && !summary.native_load_performed
        && !summary.render_performed
        && !summary.aex_loaded
        && !summary.worker_started
        && !summary.broker_load_or_render_allowed
        && !summary.ofx_route_allowed
        && !summary.ae_invoked
        && !summary.private_payload_copied
        && summary.fixture_gate_status.as_deref() == Some("review_queue_not_approved")
        && !summary.fixture_selected
        && !summary.fixture_approval_approved
        && !summary.fixture_loader_enabled
        && !summary.fixture_real_aex_load_enabled
        && !summary.fixture_render_png_enabled
        && summary.loader_gate_status.as_deref() == Some("loader_gate_not_opened")
        && !summary.loader_gate_approved
        && !summary.loader_gate_loader_enabled
        && !summary.loader_gate_real_aex_load_enabled
        && summary.loader_gate_open_candidate_count == 0
        && summary.identity_smoke_status.as_deref() == Some("fixture_identity_smoke_ready_no_load")
        && !summary.identity_smoke_aex_loaded
        && !summary.identity_smoke_ofx_route_invoked
        && !summary.identity_smoke_aex_render_correctness_evidence
        && summary.ofx_contract_status.as_deref() == Some("deferred-contract-only")
        && !summary.ofx_contract_review_approved
        && !summary.ofx_contract_ofx_host_may_load_aex
        && !summary.ofx_contract_ofx_adapter_may_load_aex
        && !summary.ofx_contract_broker_may_load_aex
        && summary.blocked_reason_count == 0
        && !summary.input_contains_forbidden_tokens
}

fn native_stage_runtime_evidence_ready(evidence: &NativeStageRuntimeEvidence) -> bool {
    evidence.worker_identity_revalidation_required.as_deref() == Some("passed")
        && evidence.worker_attestation_required.as_deref() == Some("passed")
        && evidence.sandbox_preflight_required.as_deref() == Some("passed")
        && evidence.job_object_required.as_deref() == Some("assigned-with-kill-on-close")
        && evidence.handle_inheritance_required.as_deref()
            == Some("sentinel_not_inherited-with-explicit-handle-list")
}

fn native_stage_cleanroom_boundary_no_loader_or_sdk(
    boundary: &NativeStageCleanroomBoundary,
) -> bool {
    boundary.native_loader_calls_allowed == Some(false)
        && boundary.adobe_sdk_headers_allowed == Some(false)
        && boundary.abi_generator_allowed == Some(false)
        && boundary.third_party_effect_host_crate_allowed == Some(false)
        && boundary.third_party_pipl_crate_allowed == Some(false)
        && boundary.reuse_existing_aviutl_dynamic_loader_for_aex_allowed == Some(false)
        && boundary.pf_names_are_planning_labels_only == Some(true)
        && boundary.metadata_labels_do_not_define_abi == Some(true)
}

fn non_empty_string(value: String) -> Option<String> {
    if value.is_empty() {
        None
    } else {
        Some(value)
    }
}

fn sanitized_non_empty_string(
    value: String,
    input_contains_forbidden_tokens: bool,
) -> Option<String> {
    if input_contains_forbidden_tokens {
        None
    } else {
        non_empty_string(value)
    }
}

fn string_contains_forbidden_tokens(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    forbidden_serialized_tokens()
        .iter()
        .any(|token| text.contains(token))
}

fn loader_slice_review_contains_forbidden_tokens(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    let mut tokens = forbidden_serialized_tokens();
    tokens.extend(loader_slice_review_forbidden_tokens());
    tokens.iter().any(|token| text.contains(token))
}

fn loader_approval_contains_forbidden_tokens(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    let mut tokens = forbidden_serialized_tokens();
    tokens.extend(loader_slice_review_forbidden_tokens());
    tokens.extend(loader_approval_forbidden_tokens());
    tokens.iter().any(|token| text.contains(token))
}

fn aex_metadata_gate_contains_forbidden_tokens(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    let mut tokens = forbidden_serialized_tokens();
    tokens.extend(aex_metadata_gate_forbidden_tokens());
    tokens.iter().any(|token| text.contains(token))
}

