type OfxFacadeReadinessCliArgs = (
    PathBuf,
    PathBuf,
    PathBuf,
    Option<PathBuf>,
    Option<PathBuf>,
    Option<PathBuf>,
    Option<PathBuf>,
    Vec<PathBuf>,
    PathBuf,
);

fn parse_args() -> Result<OfxFacadeReadinessCliArgs, String> {
    let mut contract = None;
    let mut fixture_gate = None;
    let mut loader_gate = None;
    let mut native_stage_plan = None;
    let mut loader_slice_review = None;
    let mut loader_approval_report = None;
    let mut aex_metadata_gate_report = None;
    let mut capabilities = Vec::new();
    let mut capability_dir = None;
    let mut out = PathBuf::from("target")
        .join("aex-ofx-facade-readiness")
        .join("ofx-facade.local.json");
    let mut args = std::env::args().skip(1);

    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--contract" => {
                contract = args.next().map(PathBuf::from);
                if contract.is_none() {
                    return Err("--contract requires a JSON path".to_string());
                }
            }
            "--fixture-gate" => {
                fixture_gate = args.next().map(PathBuf::from);
                if fixture_gate.is_none() {
                    return Err("--fixture-gate requires a JSON path".to_string());
                }
            }
            "--loader-gate" => {
                loader_gate = args.next().map(PathBuf::from);
                if loader_gate.is_none() {
                    return Err("--loader-gate requires a JSON path".to_string());
                }
            }
            "--native-stage-plan" => {
                native_stage_plan = args.next().map(PathBuf::from);
                if native_stage_plan.is_none() {
                    return Err("--native-stage-plan requires a JSON path".to_string());
                }
            }
            "--loader-slice-review-packet" => {
                loader_slice_review = args.next().map(PathBuf::from);
                if loader_slice_review.is_none() {
                    return Err("--loader-slice-review-packet requires a JSON path".to_string());
                }
            }
            "--loader-approval-report" => {
                loader_approval_report = args.next().map(PathBuf::from);
                if loader_approval_report.is_none() {
                    return Err("--loader-approval-report requires a JSON path".to_string());
                }
            }
            "--aex-metadata-gate-report" => {
                aex_metadata_gate_report = args.next().map(PathBuf::from);
                if aex_metadata_gate_report.is_none() {
                    return Err("--aex-metadata-gate-report requires a JSON path".to_string());
                }
            }
            "--capability" => {
                let path = args
                    .next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--capability requires a JSON path".to_string())?;
                capabilities.push(path);
            }
            "--capability-dir" => {
                capability_dir = args.next().map(PathBuf::from);
                if capability_dir.is_none() {
                    return Err("--capability-dir requires a directory".to_string());
                }
            }
            "--out" => {
                out = args
                    .next()
                    .map(PathBuf::from)
                    .ok_or_else(|| "--out requires a JSON path".to_string())?;
            }
            "--help" | "-h" => {
                return Err("usage: ofx_aex_facade_readiness --contract analysis/OFX_AEX_FACADE_CONTRACT_2026-05-31.json --fixture-gate analysis/AEX_FIXTURE_REVIEW_GATE_2026-05-31.json --loader-gate target/aex-probe-readiness/loader-gate.local.json [--native-stage-plan target/aex-native-stage-plan/native-stage-plan.local.json] [--loader-slice-review-packet target/aex-loader-slice-review/loader-slice-review.local.json] [--loader-approval-report target/aex-loader-approval/approval-validation.local.json] [--aex-metadata-gate-report target/aex-metadata-gate-integration/metadata-gate.local.json] [--capability capabilities/effect.capability.json | --capability-dir target/aex-probe-readiness/capabilities] [--out target/aex-ofx-facade-readiness/ofx-facade.local.json]".to_string());
            }
            other => return Err(format!("unknown argument: {other}")),
        }
    }

    if let Some(dir) = capability_dir {
        let mut discovered = std::fs::read_dir(&dir)
            .map_err(|err| format!("failed to read capability dir {}: {err}", dir.display()))?
            .filter_map(|entry| entry.ok().map(|entry| entry.path()))
            .filter(|path| path.extension().and_then(|ext| ext.to_str()) == Some("json"))
            .collect::<Vec<_>>();
        discovered.sort();
        capabilities.extend(discovered);
    }

    Ok((
        contract.ok_or_else(|| "--contract is required".to_string())?,
        fixture_gate.ok_or_else(|| "--fixture-gate is required".to_string())?,
        loader_gate.ok_or_else(|| "--loader-gate is required".to_string())?,
        native_stage_plan,
        loader_slice_review,
        loader_approval_report,
        aex_metadata_gate_report,
        capabilities,
        out,
    ))
}

fn main() -> Result<(), Box<dyn Error>> {
    let (
        contract_path,
        fixture_gate_path,
        loader_gate_path,
        native_stage_plan_path,
        loader_slice_review_path,
        loader_approval_report_path,
        aex_metadata_gate_report_path,
        capability_paths,
        out_path,
    ) = match parse_args() {
        Ok(args) => args,
        Err(message) => {
            eprintln!("{message}");
            std::process::exit(2);
        }
    };
    let contract = std::fs::read_to_string(&contract_path)?;
    let fixture_gate = std::fs::read_to_string(&fixture_gate_path)?;
    let loader_gate = std::fs::read_to_string(&loader_gate_path)?;
    let native_stage_plan = native_stage_plan_path
        .as_ref()
        .map(std::fs::read_to_string)
        .transpose()?;
    let loader_slice_review = loader_slice_review_path
        .as_ref()
        .map(std::fs::read_to_string)
        .transpose()?;
    let loader_approval_report = loader_approval_report_path
        .as_ref()
        .map(std::fs::read_to_string)
        .transpose()?;
    let aex_metadata_gate_report = aex_metadata_gate_report_path
        .as_ref()
        .map(std::fs::read_to_string)
        .transpose()?;
    let capability_texts = capability_paths
        .iter()
        .map(std::fs::read_to_string)
        .collect::<Result<Vec<_>, _>>()?;
    let capability_refs = capability_texts
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    let report = plan_ofx_facade_readiness_json_with_all_evidence(OfxFacadeReadinessJsonInputs {
        contract_json: &contract,
        fixture_gate_json: &fixture_gate,
        loader_gate_json: &loader_gate,
        native_stage_plan_json: native_stage_plan.as_deref(),
        loader_slice_review_json: loader_slice_review.as_deref(),
        loader_approval_report_json: loader_approval_report.as_deref(),
        aex_metadata_gate_report_json: aex_metadata_gate_report.as_deref(),
        capability_jsons: &capability_refs,
    })?;
    write_ofx_facade_report_create_new(&out_path, &report)?;
    println!("{}", out_path.display());
    Ok(())
}

pub fn validate_ofx_facade_report_output_path(path: &Path) -> Result<(), String> {
    if path_has_traversal(path) {
        return Err("OFX readiness report path must not contain traversal components".to_string());
    }
    if !path_has_extension(path, "json") {
        return Err("OFX readiness report path must have .json extension".to_string());
    }
    if !output_is_under_target_root(path) {
        return Err(
            "OFX readiness report path must be under target/aex-ofx-facade-readiness".to_string(),
        );
    }
    Ok(())
}

pub fn write_ofx_facade_report_create_new(path: &Path, text: &str) -> Result<(), Box<dyn Error>> {
    validate_ofx_facade_report_output_path(path)?;
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    if !output_parent_canonical_is_under_target_root(path) {
        return Err(
            "OFX readiness report parent must resolve under target/aex-ofx-facade-readiness".into(),
        );
    }
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .map_err(|err| {
            if err.kind() == ErrorKind::AlreadyExists {
                std::io::Error::new(
                    ErrorKind::AlreadyExists,
                    "OFX readiness report already exists",
                )
            } else {
                err
            }
        })?;
    file.write_all(text.as_bytes())?;
    file.write_all(b"\n")?;
    Ok(())
}

fn output_parent_canonical_is_under_target_root(path: &Path) -> bool {
    let Some(parent) = path.parent() else {
        return false;
    };
    let Ok(root) = std::fs::canonicalize(target_root()) else {
        return false;
    };
    let Ok(parent) = std::fs::canonicalize(parent) else {
        return false;
    };
    parent.starts_with(root)
}

fn target_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("target")
        .join("aex-ofx-facade-readiness")
}

fn output_is_under_target_root(path: &Path) -> bool {
    absolute_like(path).starts_with(absolute_like(&target_root()))
}

fn absolute_like(path: &Path) -> PathBuf {
    if path.is_absolute() {
        path.to_path_buf()
    } else {
        Path::new(env!("CARGO_MANIFEST_DIR")).join(path)
    }
}

fn path_has_extension(path: &Path, expected: &str) -> bool {
    path.extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case(expected))
}

fn path_has_traversal(path: &Path) -> bool {
    path.components().any(|component| {
        matches!(
            component,
            std::path::Component::ParentDir | std::path::Component::CurDir
        )
    })
}
